<script setup lang="ts">
import { computed,onMounted,reactive,ref } from 'vue'; import { ElMessage,ElMessageBox } from 'element-plus'; import { api } from '../api'; import type { Connection } from '../types'
const data=ref<any>({profiles:{},legacy_sources:{}}),path=ref(''),recursive=ref(true)
const aiConnections=ref<Connection[]>([]),aiSaving=ref(false)
const aiModels=reactive({text:'',image:''})
const concurrency=reactive({text:5,image:3}),concurrencySaving=ref(false)
const aiPrice=reactive({input:2.5,output:15,image:0.1}),priceSaving=ref(false)
async function saveAiPrice(){
  const connections=aiConnections.value.filter(c=>c.enabled&&['ai_chat','ai_image'].includes(c.provider)&&new URL(c.base_url).hostname.endsWith('micuapi.ai'));
  if(!connections.length)return ElMessage.warning('未找到启用的 micuapi 连接');
  const rows=connections.flatMap(c=>Array.from(new Set([String(c.config?.default_model||c.config?.model||''),...modelOptions(c)])).filter(Boolean).map(model=>({host:new URL(c.base_url).hostname,kind:c.provider==='ai_chat'?'text':'image',model,currency:'CNY',...(c.provider==='ai_chat'?{mode:'per_million_tokens',input:aiPrice.input,output:aiPrice.output}:{mode:'per_image',rate:aiPrice.image})})));
  const unique=[...new Map(rows.map(r=>[`${r.host}/${r.kind}/${r.model}`,r])).values()];
  const keys=new Set(unique.map(r=>`${r.host}/${r.kind}/${r.model}`));
  const retained=(data.value.profiles?.ai_pricing||[]).filter((r:any)=>!keys.has(`${r.host}/${r.kind}/${r.model}`));
  priceSaving.value=true;try{await api.put('/settings/ai_pricing',{value:[...retained,...unique]});ElMessage.success('单价已保存，仅用于后续请求估算；历史单价不变');await load()}finally{priceSaving.value=false}
}
async function saveConcurrency(){concurrencySaving.value=true;try{await api.put('/settings/ai_concurrency',{value:{...concurrency}});ElMessage.success('并发设置已保存，后续请求使用新上限；在途请求继续完成')}finally{concurrencySaving.value=false}}
const textConnection=computed(()=>aiConnections.value.find(x=>x.provider==='ai_chat'&&x.enabled))
const imageConnection=computed(()=>aiConnections.value.find(x=>x.provider==='ai_image'&&x.enabled))
const modelOptions=(connection?:Connection)=>Array.from(new Set(((connection?.config?.models as string[])||[]).filter(Boolean)))
const legacyRows=computed(()=>Object.entries(data.value.legacy_sources||{}).map(([key,value]:any)=>({name:key,path:value.root,exists:value.available})))
const profileText=reactive<Record<string,string>>({}); const labels:Record<string,string>={pricing:'定价参数',finance:'汇率与财务',copywriting:'文案规则',image_generation:'图片生成',size_chart:'尺码图',watermark:'水印',ai_pod:'AI POD 与超分辨率'}
async function load(){data.value=await api.get('/settings');Object.assign(concurrency,data.value.ai_concurrency||{text:5,image:3});for(const [key,value] of Object.entries(data.value.profiles||{}))profileText[key]=JSON.stringify(value,null,2);aiConnections.value=(await api.get<any>('/connections')).items;aiModels.text=String(textConnection.value?.config?.default_model||textConnection.value?.config?.model||'gpt-5.6-terra');aiModels.image=String(imageConnection.value?.config?.default_model||imageConnection.value?.config?.model||'gpt-image-2');const prices=data.value.profiles?.ai_pricing||[];const t=prices.find((p:any)=>p.kind==='text'&&p.model===aiModels.text&&p.host===new URL(textConnection.value?.base_url||'https://invalid').hostname);const i=prices.find((p:any)=>p.kind==='image'&&p.model===aiModels.image&&p.host===new URL(imageConnection.value?.base_url||'https://invalid').hostname);if(t){aiPrice.input=Number(t.input);aiPrice.output=Number(t.output)}if(i)aiPrice.image=Number(i.rate)}
async function saveAiModels(){if(!textConnection.value||!imageConnection.value)return ElMessage.warning('请先在接口中心启用文字 AI 和生图 AI 接口');if(!aiModels.text.trim()||!aiModels.image.trim())return ElMessage.warning('模型名称不能为空');aiSaving.value=true;try{const textModels=Array.from(new Set([aiModels.text.trim(),...modelOptions(textConnection.value)]));const imageModels=Array.from(new Set([aiModels.image.trim(),...modelOptions(imageConnection.value)]));await Promise.all([api.patch(`/connections/${textConnection.value.id}`,{config:{...textConnection.value.config,default_model:aiModels.text.trim(),models:textModels}}),api.patch(`/connections/${imageConnection.value.id}`,{config:{...imageConnection.value.config,default_model:aiModels.image.trim(),models:imageModels}})]);ElMessage.success('AI 模型设置已保存，新任务将使用所选模型');await load()}finally{aiSaving.value=false}}
async function migrate(dry:boolean){if(!dry)await ElMessageBox.confirm('迁移会写入新 ERP 数据库，但不会修改旧目录。确认执行？','执行迁移',{type:'warning'});await api.post('/jobs',{type:'legacy_migration',payload:{dry_run:dry},priority:50});ElMessage.success(dry?'预演任务已创建':'迁移任务已创建')}
async function indexAssets(){if(!path.value)return ElMessage.warning('请输入历史图片目录');await api.post('/jobs',{type:'asset_index',payload:{root:path.value,recursive:recursive.value,read_only:true},priority:10});ElMessage.success('资产索引任务已创建')}
async function saveProfile(key:string){try{await api.put(`/settings/${key}`,{value:JSON.parse(profileText[key])});ElMessage.success(`${labels[key]||key}已保存`)}catch(error){if(error instanceof SyntaxError)ElMessage.error('配置格式不正确，请检查逗号和引号');else throw error}}
onMounted(load)
</script>
<template><div class="page-stack">
<section class="panel"><div class="panel-head"><div><h2>micuapi 费用估算</h2><p>保存到当前已配置的 micuapi 模型。按返回用量估算；未返回用量、缓存计价不明或请求结果不明时待核算。</p></div><el-button type="primary" :loading="priceSaving" @click="saveAiPrice">保存单价</el-button></div><div class="ai-model-settings"><el-form label-width="190"><el-form-item label="文字输入（元/百万 token）"><el-input-number v-model="aiPrice.input" :min="0" :precision="4"/></el-form-item><el-form-item label="文字输出（元/百万 token）"><el-input-number v-model="aiPrice.output" :min="0" :precision="4"/></el-form-item><el-form-item label="图片（元/张）"><el-input-number v-model="aiPrice.image" :min="0" :precision="4"/></el-form-item></el-form></div></section>
<section class="panel"><div class="panel-head"><div><h2>AI 模型设置</h2><p>分别指定文字生成/视觉分析模型和图片生成模型；保存后只影响新建任务</p></div><el-button type="primary" :loading="aiSaving" @click="saveAiModels">保存模型设置</el-button></div><div class="ai-model-settings"><el-form label-width="150"><el-form-item label="文字与视觉模型"><el-select v-model="aiModels.text" filterable allow-create default-first-option placeholder="输入或选择模型名称"><el-option v-for="model in modelOptions(textConnection)" :key="model" :label="model" :value="model"/></el-select><span class="model-tip">用于俄文标题、描述、属性建议和商品视觉分析</span></el-form-item><el-form-item label="图片生成模型"><el-select v-model="aiModels.image" filterable allow-create default-first-option placeholder="输入或选择模型名称"><el-option v-for="model in modelOptions(imageConnection)" :key="model" :label="model" :value="model"/></el-select><span class="model-tip">用于生成和重新生成商品主图</span></el-form-item></el-form><el-alert v-if="!textConnection||!imageConnection" title="文字 AI 或生图 AI 接口尚未启用，请先到接口中心完成配置" type="warning" :closable="false" show-icon/></div></section>
<section class="panel"><div class="panel-head"><div><h2>AI 并发设置</h2><p>本机各模块共享上限；文字与视觉 5 路、生图 3 路为起始建议，可按服务商额度调整</p></div><el-button type="primary" :loading="concurrencySaving" @click="saveConcurrency">保存并发设置</el-button></div><div class="ai-model-settings"><el-form label-width="150"><el-form-item label="文字与视觉并发"><el-input-number v-model="concurrency.text" :min="1" :max="16" :precision="0"/></el-form-item><el-form-item label="生图并发"><el-input-number v-model="concurrency.image" :min="1" :max="8" :precision="0"/></el-form-item></el-form><p class="model-tip">用于 micuapi 等 AI 连接。达到上限会排队；遇到 429 会冷却后续请求。降低上限不会中断已发送请求。不是每分钟请求配额，也不改变平台建品、库存和采购的执行顺序。</p></div></section>
<section class="panel"><div class="panel-head"><div><h2>业务参数 B1–B7</h2><p>按功能独立保存，可以随时修改；保存后只影响新建任务</p></div></div><el-collapse><el-collapse-item v-for="(_value,key) in data.profiles||{}" :key="key" :title="labels[String(key)]||String(key)" :name="key"><div class="profile-editor"><el-input v-model="profileText[String(key)]" type="textarea" :rows="10"/><el-button type="primary" @click="saveProfile(String(key))">保存这一组</el-button></div></el-collapse-item></el-collapse></section>
<section class="panel"><div class="panel-head"><div><h2>旧系统迁移</h2><p>支持重复执行与预演；凭据只在内存中解密并重新加密</p></div><div><el-button @click="migrate(true)">先预演</el-button><el-button type="primary" @click="migrate(false)">执行迁移</el-button></div></div><el-table :data="legacyRows"><el-table-column prop="name" label="系统"/><el-table-column prop="path" label="目录" min-width="360" show-overflow-tooltip/><el-table-column label="状态"><template #default="s">{{s.row.exists?'可读取':'未发现'}}</template></el-table-column></el-table></section>
<section class="panel"><div class="panel-head"><div><h2>历史图片原地索引</h2><p>只保存路径、哈希和尺寸；删除 ERP 记录不会删除原始图片</p></div></div><div class="toolbar"><el-input v-model="path" placeholder="例如 D:\历史图片"/><el-checkbox v-model="recursive">包含子目录</el-checkbox><el-button type="primary" @click="indexAssets">建立索引</el-button></div></section>
</div></template>
<style scoped>.ai-model-settings{padding:22px}.ai-model-settings .el-select{width:min(100%,460px)}.model-tip{display:block;width:100%;margin-top:6px;color:var(--muted);font-size:12px}</style>
